/* The tables of M27 · Staff attendance and leave. */

/** Expected working hours. */
export const workSchedules = defineTable(
  'work_schedules',
  { module: 'M27', scope: 'org' },
  {
    ...baseColumns,
    /** "Teaching staff — summer" */
    name: text().notNull(),
    /** empty means usable by any branch */
    branchId: uuid().references((): AnyPgColumn => branches.id),
    /** seven entries `{ weekday, isOff, start?, end? }` */
    days: jsonb().notNull(),
    lateGraceMinutes: integer().notNull().default(10),
    /** arriving later than this counts as half a day */
    halfDayAfterMinutes: integer().notNull().default(120),
    earlyLeaveGraceMinutes: integer().notNull().default(10),
    /** for seasonal schedules */
    effectiveFrom: dateStr(),
    effectiveTo: dateStr(),
    /** one default per branch */
    isDefault: boolean().notNull().default(false),
    isActive: boolean().notNull().default(true),
  },
  (t) => [
    uniqueIndex('work_schedules_name_uq').on(t.orgId, t.name).where(live(t)),
    uniqueIndex('work_schedules_default_uq')
      .on(t.orgId, sql`coalesce(${t.branchId}, '00000000-0000-0000-0000-000000000000'::uuid)`)
      .where(sql`${t.isDefault} and ${t.deletedAt} is null`),
  ],
);

/** One row per staff member per day. */
