/** One row per staff member, leave type and leave year. */
export const leaveBalances = defineTable(
  'leave_balances',
  { module: 'M27', scope: 'org' },
  {
    ...baseColumns,
    staffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    leaveTypeId: uuid()
      .references((): AnyPgColumn => leaveTypes.id)
      .notNull(),
    /** the year in which the leave year starts */
    leaveYear: integer().notNull(),
    /** carried forward */
    opening: decimal(5, 1).notNull().default(0),
    accrued: decimal(5, 1).notNull().default(0),
    used: decimal(5, 1).notNull().default(0),
    /** requested, not yet decided */
    pending: decimal(5, 1).notNull().default(0),
    adjusted: decimal(5, 1).notNull().default(0),
    encashed: decimal(5, 1).notNull().default(0),
    /** generated: `opening + accrued + adjusted - used - pending - encashed` */
    available: decimal(5, 1).generatedAlwaysAs(
      (): SQL =>
        sql`${leaveBalances.opening} + ${leaveBalances.accrued} + ${leaveBalances.adjusted} - ${leaveBalances.used} - ${leaveBalances.pending} - ${leaveBalances.encashed}`,
    ),
  },
  (t) => [
    uniqueIndex('leave_balances_staff_leave_type_leave_year_uq')
      .on(t.staffId, t.leaveTypeId, t.leaveYear)
      .where(live(t)),
  ],
);

